{
  "ok": true,
  "sorting_only": true,
  "schema": {
    "$defs": {
      "SortDimension": {
        "additionalProperties": false,
        "properties": {
          "formula_id": {
            "enum": [
              "F1",
              "F2",
              "F3",
              "F4",
              "F5",
              "F6",
              "F7",
              "F8",
              "F9",
              "F15",
              "F16",
              "F19"
            ],
            "title": "Formula Id",
            "type": "string"
          },
          "weight": {
            "anyOf": [
              {
                "exclusiveMinimum": 0.0,
                "type": "number"
              },
              {
                "pattern": "^(?!^[-+.]*$)[+-]?0*\\d*\\.?\\d*$",
                "type": "string"
              }
            ],
            "title": "Weight"
          },
          "low": {
            "anyOf": [
              {
                "type": "number"
              },
              {
                "pattern": "^(?!^[-+.]*$)[+-]?0*\\d*\\.?\\d*$",
                "type": "string"
              }
            ],
            "title": "Low"
          },
          "high": {
            "anyOf": [
              {
                "type": "number"
              },
              {
                "pattern": "^(?!^[-+.]*$)[+-]?0*\\d*\\.?\\d*$",
                "type": "string"
              }
            ],
            "title": "High"
          },
          "direction": {
            "enum": [
              "higher",
              "lower"
            ],
            "title": "Direction",
            "type": "string"
          },
          "essential": {
            "default": true,
            "title": "Essential",
            "type": "boolean"
          },
          "benchmark_reference": {
            "minLength": 1,
            "title": "Benchmark Reference",
            "type": "string"
          }
        },
        "required": [
          "formula_id",
          "weight",
          "low",
          "high",
          "direction",
          "benchmark_reference"
        ],
        "title": "SortDimension",
        "type": "object"
      }
    },
    "additionalProperties": false,
    "properties": {
      "version": {
        "minLength": 1,
        "title": "Version",
        "type": "string"
      },
      "dimensions": {
        "items": {
          "$ref": "#/$defs/SortDimension"
        },
        "maxItems": 12,
        "minItems": 1,
        "title": "Dimensions",
        "type": "array"
      },
      "allow_partial": {
        "default": false,
        "title": "Allow Partial",
        "type": "boolean"
      },
      "normalization": {
        "const": "external_linear_clamped_v1",
        "default": "external_linear_clamped_v1",
        "title": "Normalization",
        "type": "string"
      }
    },
    "required": [
      "version",
      "dimensions"
    ],
    "title": "SortConfig",
    "type": "object"
  }
}
